# tests/test_fbank_kaldi_parity.py — khoá `app/fbank.py` vào bản dựng THAM CHIẾU của Kaldi.
#
# VÌ SAO CẦN: `app/fbank.py` là bản cài lại bằng numpy của Kaldi fbank, và model nhúng giọng nói
# (AC1/B5) được HUẤN LUYỆN trên đúng đặc trưng đó. Lệch một tham số (cửa sổ povey vs Hann · sàn
# log float32 vs float64 · 256 vs 257 bin FFT · preemphasis mẫu đầu) **KHÔNG ném lỗi ở đâu cả** —
# nó chỉ làm vector nhúng trôi, mà vector trôi thì vẫn phân cụm được, vẫn ra một con số, vẫn cắm
# được cờ gian lận cho HR. Đây là lớp bug "không có triệu chứng" nên phải khoá bằng số cụ thể.
#
# SỐ THAM CHIẾU sinh từ `kaldi-native-fbank` (bản port C++ thẳng từ Kaldi) — CỐ Ý không đưa gói đó
# vào requirements: nó chỉ cần một lần để sinh kỳ vọng, còn image production thì giữ nhẹ. Tái sinh
# khi đổi tham số:
#     python -m venv /tmp/refvenv && /tmp/refvenv/bin/pip install kaldi-native-fbank numpy
#     # dựng OnlineFbank với ĐÚNG bộ tham số ghi trong `app/fbank.py`, in frame 0/49/97.
# Đo lúc viết: sai lệch tuyệt đối lớn nhất **3,3e-4** trên dải giá trị -16..26 (đúng mức chính xác
# float32 của bản C++), nên dung sai 2e-3 dưới đây rộng rãi mà vẫn bắt được mọi lỗi tham số.
import numpy as np

from app.fbank import compute_fbank

# Tín hiệu tất định 1s @16kHz: 3 hình sin + nhiễu seed cố định, có một quãng IM LẶNG (mẫu
# 8000..9000) để chạm sàn log — nhánh mà lỗi "dùng eps float64" chỉ lộ ra ở đó.
_RNG = np.random.default_rng(20260828)
_T = np.arange(16000) / 16000.0
SIGNAL = (0.35 * np.sin(2 * np.pi * 220 * _T)
          + 0.20 * np.sin(2 * np.pi * 1310 * _T)
          + 0.10 * np.sin(2 * np.pi * 3400 * _T)
          + 0.01 * _RNG.standard_normal(16000))
SIGNAL[8000:9000] = 0.0

