def test_fbank_khop_ban_tham_chieu_kaldi():
    """Giá trị fbank phải khớp Kaldi ở CẢ HAI thang mẫu."""
    for scale, expected in EXPECTED.items():
        feats = compute_fbank(SIGNAL, scale_to_int16=scale)
        assert feats.shape == (98, 80), f"scale={scale}: hình dạng sai {feats.shape}"
        for fi, want in zip(REF_FRAMES, expected):
            got = feats[fi]
            assert np.allclose(got, want, atol=2e-3), (
                f"scale={scale} frame {fi}: lệch tối đa "
                f"{np.abs(got - np.array(want)).max():.2e}")


def test_fbank_san_log_la_eps_FLOAT32():
    """Khung im lặng hoàn toàn phải rơi về `log(eps float32)` = −15,94, KHÔNG phải float64 (−36,04).

    Model được huấn luyện trên đặc trưng của Kaldi, mà Kaldi lấy sàn `FLT_EPSILON`. Lệch sàn làm
    MỌI khung im lặng lệch ~20 đơn vị log — và vì CMN trừ trung bình theo thời gian, sai lệch đó
    kéo theo cả những khung CÓ tiếng nói trong cùng cửa sổ.
    """
    feats = compute_fbank(SIGNAL, scale_to_int16=True)
    floor32 = np.log(np.finfo(np.float32).eps)
    # frame 51 nằm trọn trong quãng im lặng.
    assert np.allclose(feats[51], floor32, atol=1e-3)
    assert not np.allclose(feats[51], np.log(np.finfo(np.float64).eps), atol=1.0)


def test_fbank_so_khung_theo_snip_edges():
    """snip_edges=true: chỉ lấy khung NẰM TRỌN trong tín hiệu, không đệm hai đầu."""
    assert compute_fbank(SIGNAL[:400], scale_to_int16=True).shape == (1, 80)
    assert compute_fbank(SIGNAL[:399], scale_to_int16=True).shape == (0, 80)
    assert compute_fbank(SIGNAL[:560], scale_to_int16=True).shape == (2, 80)


def test_fbank_hai_thang_mau_khac_nhau_that():
    """`scale_to_int16` phải ĐỔI kết quả — nếu không thì cờ đó là cột chết và đặt sai nó sẽ
    không bao giờ bị phát hiện."""
    a = compute_fbank(SIGNAL, scale_to_int16=False)
    b = compute_fbank(SIGNAL, scale_to_int16=True)
    assert not np.allclose(a, b)
    # Chênh lệch là hằng số log(32768²) trên bin CÒN NĂNG LƯỢNG (bin chạm sàn log thì không).
    live = a > np.log(np.finfo(np.float32).eps) + 1.0
    assert np.allclose((b - a)[live], 2 * np.log(32768.0), atol=1e-3)
